import fs from 'node:fs';

function read(path){return fs.readFileSync(path,'utf8');}
function write(path,text){fs.writeFileSync(path,text);}
function exact(path,before,after){const text=read(path);if(!text.includes(before))throw new Error(`${path}: exact target not found: ${before.slice(0,100)}`);write(path,text.replace(before,after));}
function rx(path,re,after){const text=read(path);if(!re.test(text))throw new Error(`${path}: regex target not found: ${re}`);write(path,text.replace(re,after));}
function append(path,text){const current=read(path);if(!current.includes(text.trim()))write(path,current+text);}

