append('verify-complete.mjs',`\n// Reliability hardening: execution routing, independence, evidence sufficiency, contradictions, stability, and regression lifecycle.\n{\n const p=project('JOB-RELIABILITY-HARDENING');Object.assign(p.job,{CURRENT_SOURCE_SET_VERSION:'SOURCE-SET-v001',CURRENT_REQUIREMENTS_VERSION:'REQUIREMENTS-v001',CURRENT_TEST_SUITE_VERSION:'TEST-SUITE-v001'});const scope={inputVersion:'INPUT-v001',sourceSetVersion:'SOURCE-SET-v001',requirementsVersion:'REQUIREMENTS-v001',testSuiteVersion:'TEST-SUITE-v001'};\n const req=record('requirements',4,{MANDATORY_OPTIONAL_STATUS:'MANDATORY',STATUS:'ACTIVE'},'REQ-HARDEN');req.scope={inputVersion:'INPUT-v001',sourceSetVersion:'SOURCE-SET-v001',requirementsVersion:'REQUIREMENTS-v001'};p.projectData.requirements.push(req);\n const makeTest=(id,mode,cap='CAPABILITY',art='NONE',type='DETERMINISTIC')=>{const t=record('tests',6,{REQ_ID:'REQ-HARDEN',TEST_TYPE:type,EXECUTION_MODE:mode,REQUIRED_CAPABILITY:cap,ARTIFACT_REQUIREMENTS:art,INPUTS:'canonical input',TOOLS:cap,PROCEDURE:'controlled procedure',EXPECTED_RESULT:'SATISFIED',FAILURE_CONDITION:'VIOLATED',EVIDENCE_TO_PRESERVE:'objective evidence',STATUS:'READY'},id);t.scope=scope;t.relationships={REQ_ID:'REQ-HARDEN'};return t;};\n p.projectData.tests.push(makeTest('TEST-NATIVE-HARDEN','APPLICATION_DETERMINISTIC','CANONICAL_ARTIFACT_BYTE_IDENTITY'));let plan=engine.testExecutionPlan(p);assert(plan.items[0].operatorAction==='NO_ACTION'&&plan.items[0].executorClass==='APPLICATION','Registered application-native execution did not route to NO_ACTION.');p.projectData.tests.length=0;p.projectData.tests.push(makeTest('TEST-TOOL-HARDEN','EXTERNAL_AGENT_TOOL','CAD_IMPORT','fixture.step'));plan=engine.testExecutionPlan(p);assert(plan.items[0].operatorAction==='BLOCKED'&&!plan.items[0].executableNow,'Missing byte-backed artifact did not block external tool execution.');\n const artifact=record('artifacts',6,{FILENAME:'fixture.step',TYPE:'model/step',BYTE_SIZE:4,SHA256:'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',ROLE:'TEST_INPUT',STORAGE_REFERENCE:'indexeddb:ART-HARDEN',AVAILABILITY:'BYTES_PERSISTED_AND_VERIFIED'},'ART-HARDEN'),evidence=record('evidenceRecords',6,{ATTACHMENT_ID:'ART-HARDEN',KIND:'ARTIFACT',DESCRIPTION:'fixture',LOCATION:'indexeddb',CONTENT:'verified',STATUS:'PRESERVED'},'EVID-HARDEN');p.projectData.artifacts.push(artifact);p.projectData.evidenceRecords.push(evidence);p.projectData.tests[0].evidenceRefs=['EVID-HARDEN'];plan=engine.testExecutionPlan(p);assert(plan.items[0].operatorAction==='SEND_TO_TOOL_AGENT'&&plan.items[0].executableNow&&plan.items[0].requiredArtifactNames[0]==='fixture.step','Verified artifact did not restore exact external-tool route.');const handoff=engine.artifactHandoff(p,{stage:12,testIds:['TEST-TOOL-HARDEN']});assert(handoff.send[0].artifactId==='ART-HARDEN'&&handoff.withhold.some(x=>x.artifactIdOrCategory==='OTHER_VERIFIER_RESULTS')&&handoff.expectBack.length,'Deterministic handoff manifest is incomplete.');\n}\n{\n const p=project('JOB-INDEPENDENCE-HARDEN');p.job.CURRENT_ITERATION='ITERATION-HARDEN';const iteration=record('iterations',10,{CANDIDATE_ID:'CANDIDATE-HARDEN',STATUS:'FROZEN'},'ITERATION-HARDEN');iteration.scope={iterationId:'ITERATION-HARDEN',candidateId:'CANDIDATE-HARDEN'};p.projectData.iterations.push(iteration);const candidate=record('candidateFreezes',10,{ITERATION_ID:'ITERATION-HARDEN',COMPONENT_HASHES:{A:'abc'},STATUS:'FROZEN'},'CANDIDATE-HARDEN');candidate.scope=iteration.scope;p.projectData.candidateFreezes.push(candidate);for(let i=0;i<10;i++){const run=record('runs',11,{ITERATION_ID:'ITERATION-HARDEN',CANDIDATE_ID:'CANDIDATE-HARDEN',CONTEXT_ID:\`CTX-HARDEN-\${i}\`,CONTAMINATION_CHECK:'NONE',COMPLETE_OUTPUT:\`UNIQUE-OUTPUT-HARDEN-\${i}-LONG\`},\`RUN-HARDEN-\${i}\`);run.scope=iteration.scope;p.projectData.runs.push(run);const ctx=record('freshContexts',11,{EXTERNAL_CONTEXT_IDENTIFIER:\`external-hardening-\${i}\`,ITERATION_ID:'ITERATION-HARDEN',RUN_ID:run.id,AUTHORIZED_PROJECT_INPUTS:'frozen candidate only',CONTAMINATION_STATUS:'NONE'},\`CTX-HARDEN-\${i}\`);ctx.scope=iteration.scope;p.projectData.freshContexts.push(ctx);}let independence=engine.evaluateContextIndependence(p,{role:'RUN_BATCH',iterationId:'ITERATION-HARDEN'});assert(independence.determination==='APPLICATION_ESTABLISHED','Ten distinct clean contexts were not application-established.');p.projectData.runs[1].fields.CONTEXT_ID=p.projectData.runs[0].fields.CONTEXT_ID;independence=engine.evaluateContextIndependence(p,{role:'RUN_BATCH',iterationId:'ITERATION-HARDEN'});assert(independence.determination==='VIOLATED','Duplicate run context was not detected.');p.projectData.runs[1].fields.CONTEXT_ID='CTX-HARDEN-1';const verification={fields:{RUN_ID:'RUN-HARDEN-0',VERIFIER_CONTEXT_ID:'CTX-HARDEN-0',INDEPENDENCE_STATUS:'INDEPENDENT'}};assert(engine.evaluateContextIndependence(p,{role:'VERIFICATION',iterationId:'ITERATION-HARDEN',runId:'RUN-HARDEN-0',result:verification}).determination==='VIOLATED','Agent independence assertion overrode generator-context reuse.');\n}\n{\n const p=project('JOB-EVIDENCE-HARDEN'),req=record('requirements',4,{SOURCE_ID:'SOURCE-X'},'REQ-EVID-HARDEN'),test=record('tests',6,{REQ_ID:'REQ-EVID-HARDEN',TEST_TYPE:'MEANING',EXECUTION_MODE:'INDEPENDENT_AGENT_REVIEW',REQUIRED_CAPABILITY:'semantic review',ARTIFACT_REQUIREMENTS:'NONE',PROCEDURE:'meaning comparison'},'TEST-EVID-HARDEN'),result=record('meaningResults',23,{REQ_ID:'REQ-EVID-HARDEN',TEST_ID:'TEST-EVID-HARDEN',PRODUCT_LOCATION:'section 1',REQUIRED_MEANING:'required',OBSERVED_MEANING:'observed',EVIDENCE_BASED_COMPARISON:'matches',EXTERNAL_SOURCE_EVIDENCE:'source',DETERMINATION:'SATISFIED'},'MEANING-EVID-HARDEN');let proof=engine.evaluateEvidenceSufficiency(p,{requirement:req,test,result});assert(!proof.sufficient,'Meaning result with no canonical evidence was accepted as sufficient.');const e=record('evidenceRecords',23,{KIND:'MEANING_REVIEW',DESCRIPTION:'comparison',LOCATION:'section 1',CONTENT:'observed comparison',STATUS:'PRESERVED'},'EVID-HARDEN-2');p.projectData.evidenceRecords.push(e);result.evidenceRefs=['EVID-HARDEN-2'];proof=engine.evaluateEvidenceSufficiency(p,{requirement:req,test,result});assert(proof.sufficient,'Meaning result with canonical semantic evidence was not sufficient.');\n}\n{\n const p=project('JOB-CONTRADICTION-HARDEN');Object.assign(p.job,{CURRENT_REQUIREMENTS_VERSION:'REQUIREMENTS-v001',CURRENT_TEST_SUITE_VERSION:'TEST-SUITE-v001',CURRENT_PRODUCT_ID:'PRODUCT-HARDEN'});const scope={inputVersion:'INPUT-v001',requirementsVersion:'REQUIREMENTS-v001',testSuiteVersion:'TEST-SUITE-v001',productId:'PRODUCT-HARDEN'},test=record('tests',6,{REQ_ID:'REQ-C',TEST_TYPE:'DETERMINISTIC',EXECUTION_MODE:'EXTERNAL_AGENT_TOOL',REQUIRED_CAPABILITY:'tool',ARTIFACT_REQUIREMENTS:'NONE',STATUS:'READY'},'TEST-C');test.scope=scope;p.projectData.tests.push(test);const d=record('deterministicResults',22,{TEST_ID:'TEST-C',DETERMINATION:'SATISFIED'},'RESULT-C-D'),m=record('meaningResults',23,{REQ_ID:'REQ-C',TEST_ID:'TEST-C',DETERMINATION:'VIOLATED'},'RESULT-C-M');d.scope=scope;m.scope=scope;p.projectData.deterministicResults.push(d);p.projectData.meaningResults.push(m);assert(engine.detectCurrentContradictions(p).some(x=>x.type==='PRODUCT_EVIDENCE_CONTRADICTION'),'Deterministic/meaning contradiction was not detected.');\n}\nconsole.log(JSON.stringify({reliabilityHardeningDeterministic:true},null,2));\n`);

append('verify-ingestion.mjs',`\n// Observable generator/verifier context reuse must fail before canonical mutation.\n{\n let p=makeProject('JOB-INGEST-INDEPENDENCE');p.job.CURRENT_ITERATION='ITERATION-INGEST';const iteration={id:'ITERATION-INGEST',stage:10,active:true,scope:{iterationId:'ITERATION-INGEST',candidateId:'CANDIDATE-INGEST'},fields:{ITERATION_ID:'ITERATION-INGEST',CANDIDATE_ID:'CANDIDATE-INGEST'}};p.projectData.iterations.push(iteration);const run={id:'RUN-INGEST',stage:11,active:true,scope:{iterationId:'ITERATION-INGEST',candidateId:'CANDIDATE-INGEST'},fields:{RUN_ID:'RUN-INGEST',ITERATION_ID:'ITERATION-INGEST',CANDIDATE_ID:'CANDIDATE-INGEST',CONTEXT_ID:'CTX-GENERATOR'}};p.projectData.runs.push(run);const pr=promptFor(p,12);const e=validEnvelope(p,12,pr);e.records={verification:[{tempKey:'verification-1',fields:{VERIFIER:'reviewer',VERIFIER_CONTEXT_ID:'CTX-GENERATOR',INDEPENDENCE_STATUS:'INDEPENDENT',INPUTS:'run',PROCEDURE:'verify',EXPECTED_RESULT:'pass',OBSERVED_RESULT:'pass',EXACT_EVIDENCE:'evidence',DETERMINATION:'SATISFIED'},relationships:{REQ_ID:{recordId:'REQ-DOES-NOT-MATTER'},RUN_ID:{recordId:'RUN-INGEST'},TEST_ID:{recordId:'TEST-DOES-NOT-MATTER'}},evidenceRefs:['evidence-1']}]};e.evidence=[{temporaryKey:'evidence-1',kind:'WORKFLOW_EVIDENCE',description:'independence fixture',location:'fixture',content:'evidence'}];const prepared=ingestion.prepare(p,{stage:12,text:JSON.stringify(e),promptRecord:pr});assert(prepared.validation.issues.some(x=>x.code==='VERIFIER_CONTEXT_REUSE'),'Observable verifier/generator context reuse was not rejected.');assert(prepared.project.projectData.verification.length===0,'Rejected verifier-context reuse partially mutated canonical verification.');\n}\n`);

append('verify-prompt-semantics.mjs',`\n// Reliability hardening prompt semantics: false-positive analysis and deterministic handoff language are permanent.\n{\n const p=project('JOB-PROMPT-HARDENING');const stage6=prompts.buildPromptRecord(6,p).prompt;for(const token of ['falsely appear compliant','boundary conditions','partial-success cases','stale-state cases','malformed-input cases','incorrect-authority cases','wrong-artifact cases','capability-substitution cases'])assert(stage6.includes(token),\`Stage 06 prompt missing false-positive analysis token: \${token}\`);\n assert(stage6.includes('DETERMINISTIC EXECUTION / ARTIFACT HANDOFF'),'Prompt does not consume deterministic engine handoff.');\n}\n`);

console.log('Reliability hardening repair applied.');
